-- --------------------------------------------
-- Table: damage_payments
-- --------------------------------------------
DROP TABLE IF EXISTS `damage_payments`;
CREATE TABLE `damage_payments` (
  `id` int(11) NOT NULL AUTO_INCREMENT,
  `liability_id` int(11) NOT NULL,
  `payment_quantity` int(11) NOT NULL,
  `unit_cost` decimal(14,2) NOT NULL DEFAULT 0.00,
  `payment_amount` decimal(14,2) NOT NULL DEFAULT 0.00 COMMENT 'Actual payment amount',
  `amount` decimal(14,2) NOT NULL DEFAULT 0.00 COMMENT 'Explicit payment amount (not generated)',
  `notes` text DEFAULT NULL,
  `created_by` int(11) DEFAULT NULL,
  `paid_at` timestamp NOT NULL DEFAULT current_timestamp(),
  `created_at` timestamp NOT NULL DEFAULT current_timestamp(),
  PRIMARY KEY (`id`),
  KEY `idx_liability_id` (`liability_id`),
  KEY `idx_paid_at` (`paid_at`),
  KEY `created_by` (`created_by`),
  KEY `idx_damage_payments_liability_id` (`liability_id`),
  KEY `idx_damage_payments_paid_at` (`paid_at`),
  CONSTRAINT `damage_payments_ibfk_1` FOREIGN KEY (`liability_id`) REFERENCES `damage_liabilities` (`id`),
  CONSTRAINT `damage_payments_ibfk_2` FOREIGN KEY (`created_by`) REFERENCES `users` (`id`) ON DELETE SET NULL
) ENGINE=InnoDB AUTO_INCREMENT=12 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci;

