-- --------------------------------------------
-- Table: leftovers
-- --------------------------------------------
DROP TABLE IF EXISTS `leftovers`;
CREATE TABLE `leftovers` (
  `id` int(11) NOT NULL AUTO_INCREMENT,
  `stock_out_id` int(11) NOT NULL,
  `returned_quantity` int(11) NOT NULL,
  `unit_cost_at_time` decimal(12,2) NOT NULL DEFAULT 0.00,
  `total_value` decimal(14,2) GENERATED ALWAYS AS (`returned_quantity` * `unit_cost_at_time`) STORED,
  `notes` text DEFAULT NULL,
  `created_by` int(11) DEFAULT NULL,
  `created_at` timestamp NOT NULL DEFAULT current_timestamp(),
  PRIMARY KEY (`id`),
  KEY `idx_stock_out_id` (`stock_out_id`),
  KEY `created_by` (`created_by`),
  KEY `idx_leftovers_stock_out_id` (`stock_out_id`),
  KEY `idx_leftovers_created_at` (`created_at`),
  CONSTRAINT `leftovers_ibfk_1` FOREIGN KEY (`stock_out_id`) REFERENCES `stock_out` (`id`),
  CONSTRAINT `leftovers_ibfk_2` FOREIGN KEY (`created_by`) REFERENCES `users` (`id`) ON DELETE SET NULL
) ENGINE=InnoDB AUTO_INCREMENT=3 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci;

