-- --------------------------------------------
-- Table: stock_adjustments
-- --------------------------------------------
DROP TABLE IF EXISTS `stock_adjustments`;
CREATE TABLE `stock_adjustments` (
  `id` int(11) NOT NULL AUTO_INCREMENT,
  `item_id` int(11) NOT NULL,
  `adjustment_type` enum('increase','decrease') NOT NULL,
  `quantity` int(11) NOT NULL,
  `unit_cost_at_time` decimal(12,2) NOT NULL DEFAULT 0.00,
  `total_cost` decimal(14,2) GENERATED ALWAYS AS (`quantity` * `unit_cost_at_time`) STORED,
  `reason` varchar(255) NOT NULL,
  `notes` text DEFAULT NULL,
  `created_by` int(11) DEFAULT NULL,
  `created_at` timestamp NOT NULL DEFAULT current_timestamp(),
  PRIMARY KEY (`id`),
  KEY `idx_item_id` (`item_id`),
  KEY `idx_adjustment_type` (`adjustment_type`),
  KEY `idx_reason` (`reason`),
  KEY `created_by` (`created_by`),
  KEY `idx_stock_adjustments_date` (`created_at`),
  KEY `idx_stock_adjustments_item_id` (`item_id`),
  KEY `idx_stock_adjustments_type` (`adjustment_type`),
  CONSTRAINT `stock_adjustments_ibfk_1` FOREIGN KEY (`item_id`) REFERENCES `items` (`id`),
  CONSTRAINT `stock_adjustments_ibfk_2` FOREIGN KEY (`created_by`) REFERENCES `users` (`id`) ON DELETE SET NULL
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci;

-- --------------------------------------------
-- Table: stock_in
-- --------------------------------------------
DROP TABLE IF EXISTS `stock_in`;
CREATE TABLE `stock_in` (
  `id` int(11) NOT NULL AUTO_INCREMENT,
  `item_id` int(11) NOT NULL,
  `quantity` int(11) NOT NULL,
  `unit_price` decimal(12,2) NOT NULL DEFAULT 0.00,
  `total_cost` decimal(14,2) GENERATED ALWAYS AS (`quantity` * `unit_price`) STORED,
  `supplier` varchar(200) DEFAULT NULL,
  `supplier_type` varchar(50) DEFAULT NULL,
  `reference_number` varchar(100) DEFAULT NULL,
  `notes` text DEFAULT NULL,
  `department_id` int(11) DEFAULT NULL,
  `date` date NOT NULL,
  `created_by` int(11) DEFAULT NULL,
  `created_at` timestamp NOT NULL DEFAULT current_timestamp(),
  PRIMARY KEY (`id`),
  KEY `idx_item_id` (`item_id`),
  KEY `idx_date` (`date`),
  KEY `idx_supplier` (`supplier`),
  KEY `created_by` (`created_by`),
  KEY `idx_stock_in_date` (`date`),
  KEY `idx_stock_in_item_id` (`item_id`),
  KEY `idx_stock_in_supplier` (`supplier`(100)),
  KEY `idx_stock_in_supplier_type` (`supplier_type`),
  KEY `idx_stock_in_reference` (`reference_number`),
  KEY `idx_stock_in_created_at` (`created_at`),
  KEY `idx_stock_in_department_id` (`department_id`),
  CONSTRAINT `stock_in_ibfk_1` FOREIGN KEY (`item_id`) REFERENCES `items` (`id`),
  CONSTRAINT `stock_in_ibfk_2` FOREIGN KEY (`created_by`) REFERENCES `users` (`id`) ON DELETE SET NULL
) ENGINE=InnoDB AUTO_INCREMENT=11 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci;

